const $=id=>document.getElementById(id);let token='';const notice=s=>$('notice').textContent=s;
const pages={requests:['admin.html','Demandes'],crm:['crm.html','CRM'],quotes:['quotes.html','Devis'],tenders:['tenders.html','Appels d’offres'],consultants:['consultants.html','Consultants'],missions:['missions.html','Missions'],billing:['billing.html','Finance'],direction:['direction.html','Direction'],accounts:['accounts.html','Comptes'],audit:['audit.html','Journal'], 'my-activity':['my-activity.html','Mes CRA']};
async function api(action,data){const r=await fetch('/api/auth/'+action,{method:'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw Error(d.error);return d}
for(const [id,action] of [['activate','activate'],['signin','login']])$(id).onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const d=await api(action,Object.fromEntries(new FormData(e.target)));e.target.reset();if(action==='activate'){notice('Activation effectuée. Connectez-vous avec votre mot de passe.');return}token=d.token;$('session').value=token;$('role').textContent=d.role;$('modules').replaceChildren();for(const [resource,[url,label]] of Object.entries(pages)){const mode=d.permissions[resource]||d.permissions['*'];if(!mode)continue;const a=document.createElement('a');a.className='count';a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=label+' — '+(mode.includes('W')?'Lecture / écriture':'Lecture');$('modules').append(a)}$('workspace').hidden=false;$('login').hidden=true;notice('Connecté.')}catch(err){notice(err.message)}finally{b.disabled=false}};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(token);notice('Clé copiée.')}catch{notice('Copie indisponible.')}};
$('logout').onclick=async()=>{try{await api('logout',{});token='';$('session').value='';$('modules').replaceChildren();$('workspace').hidden=true;$('login').hidden=false;notice('Session révoquée.')}catch(e){notice(e.message)}};
